cat > $TMPDIR/scan_shp.py <<'EOF'
import re, os
pat = re.compile(r'(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb_header_pointer\s*\(')
results = []
for dirpath, dirs, files in os.walk('.'):
    if any(x in dirpath for x in ('/tools','/Documentation','/samples','/rust')): continue
    for f in files:
        if not f.endswith('.c'): continue
        p = os.path.join(dirpath, f)
        try: lines = open(p, encoding='utf-8', errors='ignore').read().splitlines()
        except: continue
        for i, ln in enumerate(lines):
            m = pat.search(ln)
            if m:
                var = m.group(1)
                window = ' '.join(lines[i:i+9])
                has_check = re.search(r'!\s*%s\b' % re.escape(var), window) or \
                            re.search(r'%s\s*(==|!=)\s*NULL' % re.escape(var), window) or \
                            re.search(r'IS_ERR\s*\(\s*%s\b' % re.escape(var), window)
                if not has_check:
                    results.append((p, i+1, ln.strip()[:120], var))
for r in results:
    print('%s:%d: %s  [var=%s]' % r)
print('TOTAL', len(results))
EOF
python3 $TMPDIR/scan_shp.py > $TMPDIR/shp_unchecked.txt 2>&1; cat $TMPDIR/shp_unchecked.txt

